/*!
 * 轻量 Markdown 渲染（生产环境建议替换为官方 marked.min.js）
 * 暴露 window.marked.parse(text) -> HTML 字符串
 * 支持：标题/加粗/斜体/行内代码/代码块/有序无序列表/引用/分隔线/链接/图片/基础管道表格/删除线
 */
(function (global) {
  'use strict';

  function escapeHtml(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function inline(text) {
    var s = escapeHtml(text);
    s = s.replace(/!\[([^\]]*)\]\(([^\s)]+)(?:\s+"([^"]*)")?\)/g,
      '<img alt="$1" src="$2" style="max-width:100%;border-radius:8px">');
    s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
      '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
    s = s.replace(/`([^`]+)`/g, '<code class="md-code">$1</code>');
    s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    s = s.replace(/~~([^~]+)~~/g, '<del>$1</del>');
    s = s.replace(/(^|[^\w*])\*([^*\n]+)\*/g, '$1<em>$2</em>');
    return s;
  }

  function renderTable(lines) {
    var rows = lines.map(function (l) {
      return l.replace(/^\s*\|/, '').replace(/\|\s*$/, '')
        .split('|').map(function (c) { return c.trim(); });
    });
    if (rows.length < 2) return null;
    var sep = rows[1];
    if (!sep.every(function (c) { return /^:?-{2,}:?$/.test(c.replace(/\s/g, '')); }))
      return null;
    var html = '<div class="md-table-wrap"><table class="md-table"><thead><tr>';
    rows[0].forEach(function (c) { html += '<th>' + inline(c) + '</th>'; });
    html += '</tr></thead><tbody>';
    for (var i = 2; i < rows.length; i++) {
      html += '<tr>';
      rows[i].forEach(function (c) { html += '<td>' + inline(c) + '</td>'; });
      html += '</tr>';
    }
    return html + '</tbody></table></div>';
  }

  function parse(src) {
    var lines = String(src || '').replace(/\r\n/g, '\n').split('\n');
    var html = '', para = [], listStack = null, i = 0;

    function flushPara() {
      if (para.length) {
        html += '<p>' + inline(para.join(' ')) + '</p>';
        para = [];
      }
    }
    function closeList() {
      if (listStack) { html += listStack === 'ol' ? '</ol>' : '</ul>'; listStack = null; }
    }

    while (i < lines.length) {
      var line = lines[i];
      // 代码块
      var fence = line.match(/^```(\w*)\s*$/);
      if (fence) {
        flushPara(); closeList();
        var buf = [];
        i++;
        while (i < lines.length && !/^```\s*$/.test(lines[i])) { buf.push(lines[i]); i++; }
        i++;
        html += '<pre class="md-pre"><code>' + escapeHtml(buf.join('\n')) + '</code></pre>';
        continue;
      }
      // 表格
      if (/^\s*\|.*\|\s*$/.test(line) && i + 1 < lines.length &&
          /^\s*\|[\s:|-]+\|\s*$/.test(lines[i + 1])) {
        flushPara(); closeList();
        var tl = [];
        while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) { tl.push(lines[i]); i++; }
        var t = renderTable(tl);
        if (t) { html += t; continue; }
      }
      // 分隔线
      if (/^\s*(-{3,}|\*{3,}|_{3,})\s*$/.test(line)) {
        flushPara(); closeList();
        html += '<hr>';
        i++; continue;
      }
      // 标题
      var h = line.match(/^(#{1,6})\s+(.*)$/);
      if (h) {
        flushPara(); closeList();
        var lv = h[1].length;
        html += '<h' + lv + '>' + inline(h[2]) + '</h' + lv + '>';
        i++; continue;
      }
      // 引用
      if (/^\s*>\s?/.test(line)) {
        flushPara(); closeList();
        var qb = [];
        while (i < lines.length && /^\s*>\s?/.test(lines[i])) {
          qb.push(lines[i].replace(/^\s*>\s?/, '')); i++;
        }
        html += '<blockquote>' + parse(qb.join('\n')) + '</blockquote>';
        continue;
      }
      // 列表
      var ul = line.match(/^\s*[-*+]\s+(.*)$/);
      var ol = line.match(/^\s*\d+[.)]\s+(.*)$/);
      if (ul || ol) {
        flushPara();
        var type = ul ? 'ul' : 'ol';
        if (listStack !== type) { closeList(); html += '<' + type + '>'; listStack = type; }
        html += '<li>' + inline((ul || ol)[1]) + '</li>';
        i++; continue;
      }
      // 空行
      if (!line.trim()) { flushPara(); closeList(); i++; continue; }
      closeList();
      para.push(line.trim());
      i++;
    }
    flushPara(); closeList();
    return html;
  }

  global.marked = { parse: parse };
})(window);
